('2340a0e9-ec3a-5ae7-a862-c59df49170d5', 'ea20273a-8960-5975-b53b-599fa4656106', 'A horizontal line', 'C', false, 2),
('a4e27e35-b000-54ec-87af-1d642b0a56db', 'ea20273a-8960-5975-b53b-599fa4656106', 'A straight line with a negative gradient', 'D', false, 3),
('df79d797-d5e4-50ff-ad5a-5c8fb65584f0', 'd7c3583f-476b-5a9b-af47-13dddccfaec7', 'A thin slice carries a larger current', 'A', false, 0),
('f94212be-83e4-5e69-a9be-7a8675094f8c', 'd7c3583f-476b-5a9b-af47-13dddccfaec7', 'Thin slices have more charge carriers', 'B', false, 1),
('726a78ed-9f98-58e5-8bb1-3530b8b2fd46', 'd7c3583f-476b-5a9b-af47-13dddccfaec7', 'A thin slice is not affected by the field', 'C', false, 2),
('be795573-b88d-5f1e-9095-56324e21b5ed', 'd7c3583f-476b-5a9b-af47-13dddccfaec7', 'The Hall voltage is inversely proportional to the thickness, so a thin slice gives a larger voltage', 'D', true, 3),
('659ca700-6e3b-5e12-bdd4-7d99379be0e5', '6f16dc21-d05d-5210-a24b-718a6908a4d2', 'With its flat face parallel to the field', 'A', false, 0),
('5445ed8a-ee41-5019-8b42-28fe91db1431', '6f16dc21-d05d-5210-a24b-718a6908a4d2', 'With its flat face at right angles to the magnetic field', 'B', true, 1),
('0fbc9ea0-960d-55e0-a890-2ae9a1add943', '6f16dc21-d05d-5210-a24b-718a6908a4d2', 'Pointing along the field', 'C', false, 2),
('ab228d8f-69f0-55de-a8c3-90daacbd96a8', '6f16dc21-d05d-5210-a24b-718a6908a4d2', 'At 45° to the field', 'D', false, 3),
('7919fe75-0a8b-565d-a386-f12f9f59310a', '64d05774-0d89-54c0-9f60-61fb8cbc3b2b', 'Its density', 'A', false, 0),
('0d8bc39c-ab86-5d79-a5b9-9998af3f43e1', '64d05774-0d89-54c0-9f60-61fb8cbc3b2b', 'Its temperature', 'B', false, 1),
('4a9905ee-3307-5489-abd8-a6a50ac6af04', '64d05774-0d89-54c0-9f60-61fb8cbc3b2b', 'Whether its charge carriers are positive or negative', 'C', true, 2),
('84441a1b-4819-5ece-afdb-203d76d5c91d', '64d05774-0d89-54c0-9f60-61fb8cbc3b2b', 'Its resistance', 'D', false, 3),
('d79bc721-076b-536e-bc2a-4facec9f3b13', '709e9d1a-5cbd-54a9-bf4a-38e37a43fcba', 'Metals have a very large number of free electrons per m³, so they drift very slowly', 'A', true, 0),
('f1573d13-5a96-52ac-a7b7-160e1c4f678d', '709e9d1a-5cbd-54a9-bf4a-38e37a43fcba', 'Metals have no free electrons', 'B', false, 1),
('c66ec8b5-50aa-501c-9d62-5f78370d37ba', '709e9d1a-5cbd-54a9-bf4a-38e37a43fcba', 'Metals are not affected by magnetic fields', 'C', false, 2),
('f561babd-c4d1-5ca7-87fd-76d64b88bd91', '709e9d1a-5cbd-54a9-bf4a-38e37a43fcba', 'Metals are always very thick', 'D', false, 3),
('2ea94aaa-81b3-56a3-acad-d7ab06173e65', 'c188eacf-3136-5652-9b2b-e42f88d7622c', 'The magnetic force and the carrier''s weight', 'A', false, 0),
('da0edec7-b5d5-5648-914c-96189e13638b', 'c188eacf-3136-5652-9b2b-e42f88d7622c', 'The electric force and gravity', 'B', false, 1),
('c5bcfa5f-b755-5367-9a32-7042bec2c31c', 'c188eacf-3136-5652-9b2b-e42f88d7622c', 'The current and the voltage', 'C', false, 2),
('680d1171-ae8e-5604-b7aa-0011d4b280fe', 'c188eacf-3136-5652-9b2b-e42f88d7622c', 'The magnetic force Bqv and the electric force qE_H from the Hall field', 'D', true, 3),
('4958d134-c67a-5279-8e88-ce2162e44ff3', 'e50801b1-34d4-5ab3-b95d-f01558fb4dee', 'Otherwise the probe overheats', 'A', false, 0),
('4a975b00-546c-53e4-9b32-e4d231a88cf7', 'e50801b1-34d4-5ab3-b95d-f01558fb4dee', 'The Hall voltage is proportional to the current as well as to B', 'B', true, 1),
('d1462f50-f01d-5fb1-9e92-d473e22a29be', 'e50801b1-34d4-5ab3-b95d-f01558fb4dee', 'The field depends on the current', 'C', false, 2),
('acf50f54-0c52-5446-bb28-95d1e0d5d200', 'e50801b1-34d4-5ab3-b95d-f01558fb4dee', 'The thickness depends on the current', 'D', false, 3),
('40611449-4369-53ef-bdb1-7dfb4f14846f', '85c65930-2177-5510-b020-552a6b9f384d', 'It doubles', 'A', false, 0),
('0f2a7971-d34a-54cf-9b58-3e43431eb80a', '85c65930-2177-5510-b020-552a6b9f384d', 'It becomes zero', 'B', false, 1),
('79ba2825-ff24-5a30-a456-9865d14ad5f6', '85c65930-2177-5510-b020-552a6b9f384d', 'It reverses polarity but keeps the same size', 'C', true, 2),
('1987f3eb-27b7-5c82-98ad-8075e1e9eaec', '85c65930-2177-5510-b020-552a6b9f384d', 'It stays exactly the same', 'D', false, 3),
('e514e82e-15e7-50c3-9e85-f3f7d5a98edf', '51320d9f-cdff-551e-9b19-af160115d172', 'It halves', 'A', true, 0),
('2ce7902d-813b-58f5-b1dd-a5d507684e47', '51320d9f-cdff-551e-9b19-af160115d172', 'It doubles', 'B', false, 1),
('cc3d6b0a-9ac7-576a-8920-d2312376618d', '51320d9f-cdff-551e-9b19-af160115d172', 'It stays the same', 'C', false, 2),
('91507bf3-b0b2-575f-846f-0f1eb69725c3', '51320d9f-cdff-551e-9b19-af160115d172', 'It quadruples', 'D', false, 3),
('d678bc52-fd93-5dfa-9722-6fd12759e55c', 'c693f453-a45a-5132-8988-7e27785fedbf', '100', 'A', false, 0),
('98fa8d60-3730-50fd-956f-a94a55d4029a', 'c693f453-a45a-5132-8988-7e27785fedbf', '1', 'B', false, 1),
('516c226c-844f-5ac6-a615-905b0d45e4ea', 'c693f453-a45a-5132-8988-7e27785fedbf', '10', 'C', false, 2),
('4439daba-bade-5bcb-8f51-6ce537fc0bc1', 'c693f453-a45a-5132-8988-7e27785fedbf', '1/100', 'D', true, 3),
('0f36d456-2cb2-5909-9f87-d5d9240af762', '9c44047a-2deb-5092-bc48-832c72711fe2', 'They have the same polarity', 'A', false, 0),
('299edd92-836d-5437-a5db-d255db103dc8', '9c44047a-2deb-5092-bc48-832c72711fe2', 'They have opposite polarities, because the carriers have opposite signs', 'B', true, 1),
('72771b25-683f-5c50-8de5-7fd2ccf472f0', '9c44047a-2deb-5092-bc48-832c72711fe2', 'Only the n-type gives a Hall voltage', 'C', false, 2),
('5d97f110-2292-5cad-ac91-5933ea510f7e', '9c44047a-2deb-5092-bc48-832c72711fe2', 'Both are zero', 'D', false, 3),
('e7ed412b-8d7f-5729-bdd7-f26714bd6e9c', 'b184a41d-7b20-5661-9b24-91762d2479eb', 'Its current changes the field it measures', 'A', false, 0),
('c8008738-3032-592a-89fd-973649895d30', 'b184a41d-7b20-5661-9b24-91762d2479eb', 'The Hall voltage does not depend on B', 'B', false, 1),
('d5881549-be5b-59e0-99c2-0dcb23f0a114', 'b184a41d-7b20-5661-9b24-91762d2479eb', 'Its carrier density and thickness are not known accurately, and its output can vary with temperature', 'C', true, 2),
('714cf593-49e8-5ecd-b1a0-f69a481324b8', 'b184a41d-7b20-5661-9b24-91762d2479eb', 'The probe stores charge', 'D', false, 3),
('ba318730-2faf-5267-b3fa-afa976950d42', '1bc16681-561d-5fdd-80fd-34db170b863d', 'Making the slice wider, with the same thickness, current and field', 'A', true, 0),
('749a5e8a-3495-5a68-8729-38322d22e0c8', '1bc16681-561d-5fdd-80fd-34db170b863d', 'Making the slice thinner', 'B', false, 1),
('2c96113a-10cd-5806-a85b-82b636d15fc8', '1bc16681-561d-5fdd-80fd-34db170b863d', 'Increasing the current', 'C', false, 2),
('5ae869f3-d805-515c-90c4-fbb86180d4d6', '1bc16681-561d-5fdd-80fd-34db170b863d', 'Increasing the flux density', 'D', false, 3),
('c334b990-a5ec-5be7-9b60-8b7eaeb384cf', '50e72060-2b19-583c-932f-3558ad4e9b8f', 'The faces through which the current enters and leaves', 'A', false, 0),
('db1d03a7-7bb3-56a7-8b20-327cd16059c1', '50e72060-2b19-583c-932f-3558ad4e9b8f', 'The faces at right angles to the field only', 'B', false, 1),
('957e8a66-3049-529f-9660-6b3a95402ac5', '50e72060-2b19-583c-932f-3558ad4e9b8f', 'Any two opposite faces', 'C', false, 2),
('610b57a0-86b0-5c7e-99a5-1b01f4ac7918', '50e72060-2b19-583c-932f-3558ad4e9b8f', 'The pair of faces at right angles to both the current and the magnetic field', 'D', true, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('75b54547-f388-5146-9c76-177281239b4c', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 7, 7, 'What is thermionic emission?', NULL, 1, 'multiple_choice'::answer_type, 'The release of electrons from the surface of a heated metal', NULL, false, NULL, false, NULL, 'Heating gives some free electrons enough energy to escape the metal. Mark scheme (1 mark). B1: C (The release of electrons from the surface of a heated metal).', 1),
('f7330765-2856-5c0e-b44f-6f40fe3640c7', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 8, 8, 'In a fine-beam tube, electrons are accelerated from rest through 300 V. Using e/m = 1.76 × 10¹¹ C kg⁻¹, find their speed.', NULL, 1, 'numeric'::answer_type, '1.028e7', 'm s⁻¹', false, NULL, false, NULL, '½mv² = eV gives v = √(2(e/m)V) = √(2 × 1.76 × 10¹¹ × 300) = 1.03 × 10⁷ m s⁻¹. Mark scheme (2 marks). C1: v = √(2(e/m)V). A1: v = 1.03 × 10⁷ m s⁻¹.', 2),
('91a682a8-1613-5392-9b51-f3201f8ccced', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 9, 9, 'Cathode rays passing between two charged plates bend towards the positive plate. What does this show?', NULL, 1, 'multiple_choice'::answer_type, 'The rays carry negative charge', NULL, false, NULL, false, NULL, 'Opposite charges attract. Mark scheme (1 mark). B1: A (The rays carry negative charge).', 1),
('e456175e-3fa7-5802-9000-760c092dffbf', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 10, 10, 'An electron is accelerated from rest through 250 V. Calculate the kinetic energy it gains, in units of 10⁻¹⁷ J. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '4', '10⁻¹⁷ J', false, NULL, false, NULL, 'E_k = eV = 1.60 × 10⁻¹⁹ × 250 = 4.00 × 10⁻¹⁷ J (250 eV). Mark scheme (2 marks). C1: E_k = eV. A1: E_k = 4.0 × 10⁻¹⁷ J.', 2),
('f3d7e995-334e-52c1-ac2b-8513901bbd67', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 11, 11, 'Thomson found that cathode rays had the same e/m whatever metal the cathode was made of. What did he conclude?', NULL, 1, 'multiple_choice'::answer_type, 'The particles are a common constituent of all atoms', NULL, false, NULL, false, NULL, 'A universal e/m suggests the same particle comes from every element. Mark scheme (1 mark). B1: D (The particles are a common constituent of all atoms).', 1),
('8640e6e3-34dd-5091-bd33-d545a47bc0a5', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 12, 12, 'Using e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg, calculate the specific charge e/m of the electron, in units of 10¹¹ C kg⁻¹.', NULL, 1, 'numeric'::answer_type, '1.756', '10¹¹ C kg⁻¹', false, NULL, false, NULL, 'e/m = 1.60 × 10⁻¹⁹ ÷ 9.11 × 10⁻³¹ = 1.76 × 10¹¹ C kg⁻¹. Mark scheme (2 marks). C1: e ÷ m. A1: e/m = 1.76 × 10¹¹ C kg⁻¹.', 2),
('bb275a1f-aa01-5656-9791-80c1a452a7e8', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 13, 13, 'Why must the tube in a cathode-ray or fine-beam experiment contain very little gas?', NULL, 1, 'multiple_choice'::answer_type, 'So that the electrons are not stopped or scattered by collisions with gas molecules', NULL, false, NULL, false, NULL, 'At low pressure the mean free path is long enough for a visible beam. Mark scheme (1 mark). B1: B (So that the electrons are not stopped or scattered by collisions with gas molecules).', 1),
('cef63e88-b894-5cb2-a512-0ba61feeca9f', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 14, 14, 'A beam of electrons moving at 1.0 × 10⁷ m s⁻¹ is bent into a circle of radius 5.7 cm by a field of 1.0 mT. Deduce e/m, in units of 10¹¹ C kg⁻¹.', NULL, 1, 'numeric'::answer_type, '1.754', '10¹¹ C kg⁻¹', false, NULL, false, NULL, 'e/m = v/(Br) = 1.0 × 10⁷ ÷ (1.0 × 10⁻³ × 0.057) = 1.75 × 10¹¹ C kg⁻¹. Mark scheme (2 marks). C1: e/m = v/(Br). A1: e/m = 1.75 × 10¹¹ C kg⁻¹.', 2),
('ee26e8a8-a7b3-5c08-95fa-07982c22c73b', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 15, 15, 'Why can the path of the electrons be seen in a fine-beam tube?', NULL, 1, 'multiple_choice'::answer_type, 'The electrons excite atoms of the low-pressure gas, which then emit light', NULL, false, NULL, false, NULL, 'Collisions excite the gas atoms; they emit light as they return to lower energy levels. Mark scheme (1 mark). B1: C (The electrons excite atoms of the low-pressure gas, which then emit light).', 1),
('21641a20-aca6-5a3b-a483-035ff874b545', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 16, 16, 'Calculate the accelerating p.d. needed to give electrons a speed of 2.0 × 10⁷ m s⁻¹, using e/m = 1.76 × 10¹¹ C kg⁻¹.', NULL, 1, 'numeric'::answer_type, '1136', 'V', false, NULL, false, NULL, 'V = v²/(2e/m) = (2.0 × 10⁷)² ÷ (2 × 1.76 × 10¹¹) = 1140 V. Mark scheme (2 marks). C1: rearranged ½mv² = eV. A1: V = 1140 V.', 2),
('9c9b5a65-727b-5d59-a675-f56795565e6e', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 17, 17, 'What did Millikan''s oil-drop experiment measure directly?', NULL, 1, 'multiple_choice'::answer_type, 'The charges on individual oil drops, which were always multiples of e', NULL, false, NULL, false, NULL, 'Balancing the drops gave their charges, all whole-number multiples of 1.6 × 10⁻¹⁹ C. Mark scheme (1 mark). B1: A (The charges on individual oil drops, which were always multiples of e).', 1),
('ad8fa813-fe8b-52eb-ae11-5b18ba59540b', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 18, 18, 'Calculate the specific charge of the proton, e/mₚ, in units of 10⁷ C kg⁻¹. Take e = 1.60 × 10⁻¹⁹ C and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 1, 'numeric'::answer_type, '9.581', '10⁷ C kg⁻¹', false, NULL, false, NULL, 'e/mₚ = 1.60 × 10⁻¹⁹ ÷ 1.67 × 10⁻²⁷ = 9.58 × 10⁷ C kg⁻¹. Mark scheme (2 marks). C1: e ÷ mₚ. A1: e/m = 9.58 × 10⁷ C kg⁻¹.', 2),
('76c27235-b1f4-5262-ac62-1fa6ecaf8c02', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 19, 19, 'Thomson''s value of e/m for cathode-ray particles was about 1800 times that for hydrogen ions. Assuming equal charges, what did this suggest?', NULL, 1, 'multiple_choice'::answer_type, 'The particles are about 1800 times lighter than a hydrogen ion', NULL, false, NULL, false, NULL, 'With the same e, a larger e/m means a smaller mass. Mark scheme (1 mark). B1: D (The particles are about 1800 times lighter than a hydrogen ion).', 1),
('b6a1a85b-76a1-5648-80bf-bffeaabc68ca', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 20, 20, 'Using e/m = 1.76 × 10¹¹ C kg⁻¹ for the electron and 9.58 × 10⁷ C kg⁻¹ for the proton, calculate (e/m for the electron) ÷ (e/m for the proton).', NULL, 1, 'numeric'::answer_type, '1837', NULL, false, NULL, false, NULL, 'Ratio = 1.76 × 10¹¹ ÷ 9.58 × 10⁷ = 1840. Mark scheme (1 mark). A1: ratio = 1840.', 1),
('67795533-a97c-566b-836b-73f42f798716', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 21, 21, 'Which arrangement did Thomson use to find the speed of the cathode-ray particles?', NULL, 1, 'multiple_choice'::answer_type, 'Crossed electric and magnetic fields adjusted until the beam was undeflected, so v = E/B', NULL, false, NULL, false, NULL, 'Balancing eE = Bev gives v = E/B. Mark scheme (1 mark). B1: B (Crossed electric and magnetic fields adjusted until the beam was undeflected, so v = E/B).', 1),
('6476f16d-47e7-5597-8cca-cfa5fa572059', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 22, 22, 'In Thomson''s apparatus a beam is undeflected when E = 1.5 × 10⁴ V m⁻¹ and B = 5.0 × 10⁻⁴ T. Calculate the speed of the particles.', NULL, 1, 'numeric'::answer_type, '3e7', 'm s⁻¹', false, NULL, false, NULL, 'v = E/B = 1.5 × 10⁴ ÷ 5.0 × 10⁻⁴ = 3.0 × 10⁷ m s⁻¹. Mark scheme (2 marks). C1: v = E/B. A1: v = 3.0 × 10⁷ m s⁻¹.', 2),
('86746518-9fb4-52ba-a873-861d881542f5', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 23, 23, 'In an electron gun, why is the anode at a high positive potential relative to the cathode?', NULL, 1, 'multiple_choice'::answer_type, 'To attract and accelerate the emitted electrons towards it', NULL, false, NULL, false, NULL, 'The p.d. does work eV on each electron. Mark scheme (1 mark). B1: C (To attract and accelerate the emitted electrons towards it).', 1),
('b40eb97c-3c4f-5fea-948b-82d5849d38ac', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 24, 24, 'In a fine-beam tube, electrons accelerated through 250 V follow a circle of radius 4.4 cm in a field of 1.2 mT. Calculate e/m, in units of 10¹¹ C kg⁻¹, using e/m = 2V/(B²r²).', NULL, 2, 'numeric'::answer_type, '1.794', '10¹¹ C kg⁻¹', false, NULL, false, NULL, 'e/m = 2V/(B²r²) = 2 × 250 ÷ ((1.2 × 10⁻³)² × 0.044²) = 1.79 × 10¹¹ C kg⁻¹. Mark scheme (3 marks). C1: formula. C1: substitution. A1: e/m = 1.79 × 10¹¹ C kg⁻¹.', 3),
('6eb03207-16b3-5b18-bba4-753b0d8a3b68', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 25, 25, 'Electrons accelerated through 200 V enter a field of 0.80 mT at right angles. Using e/m = 1.76 × 10¹¹ C kg⁻¹, calculate the radius of their path, in cm.', NULL, 2, 'numeric'::answer_type, '5.959 cm', 'cm', false, NULL, false, NULL, 'r = √(2V/(e/m)) ÷ B = √(2 × 200 ÷ 1.76 × 10¹¹) ÷ 0.80 × 10⁻³ = 0.0596 m. In cm: 0.05959 × 100 = 5.96. Mark scheme (3 marks). M1: r = √(2mV/e)/B. C1: substitution. A1: r = 5.96 cm.', 3),
('4edcae42-02e7-57fb-9600-56ccb1154a47', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 26, 26, 'In a fine-beam tube at fixed B, why is the radius proportional to √V?', NULL, 2, 'multiple_choice'::answer_type, 'The speed is proportional to √V and the radius is proportional to the speed', NULL, false, NULL, false, NULL, '½mv² = eV gives v ∝ √V; r = mv/eB ∝ v. Mark scheme (3 marks). C1: v ∝ √V. C1: r ∝ v. A1: A (The speed is proportional to √V and the radius is proportional to the speed).', 3),
('8856e0ea-3303-566b-8dca-d6ca546f8df4', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 27, 27, 'Thomson''s beam is undeflected with E = 2.0 × 10⁴ V m⁻¹ and B = 1.0 mT. With the electric field removed, the beam follows a circle of radius 11.4 cm. Calculate e/m, in units of 10¹¹ C kg⁻¹.', NULL, 2, 'numeric'::answer_type, '1.754', '10¹¹ C kg⁻¹', false, NULL, false, NULL, 'v = E/B = 2.0 × 10⁴ ÷ 1.0 × 10⁻³ = 2.0 × 10⁷ m s⁻¹. e/m = v/(Br) = 2.0 × 10⁷ ÷ (1.0 × 10⁻³ × 0.114) = 1.75 × 10¹¹ C kg⁻¹. Mark scheme (4 marks). C1: v = E/B. M1: e/m = v/(Br). C1: value. A1: e/m = 1.75 × 10¹¹ C kg⁻¹.', 4),
('56532e34-1f8c-5315-a9b9-52d53b095478', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 28, 28, 'Calculate the flux density needed to make electrons accelerated through 300 V follow a circle of radius 5.0 cm, in mT. Take e/m = 1.76 × 10¹¹ C kg⁻¹.', NULL, 2, 'numeric'::answer_type, '1.168 mT', 'mT', false, NULL, false, NULL, 'B = √(2V/(e/m)) ÷ r = √(600 ÷ 1.76 × 10¹¹) ÷ 0.050 = 0.00117 T. In mT: 0.001168 × 1000 = 1.17. Mark scheme (3 marks). C1: rearranged. C1: conversion. A1: B = 1.17 mT.', 3),
('a6bf8a8a-7ac0-5e31-ad6d-ef9cd77fbbfb', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 29, 29, 'In a fine-beam tube, the accelerating p.d. is increased while B stays the same. What happens to the circle?', NULL, 2, 'multiple_choice'::answer_type, 'Its radius increases', NULL, false, NULL, false, NULL, 'Faster electrons need a larger circle: r ∝ √V. Mark scheme (3 marks). C1: v increases. C1: r ∝ v. A1: D (Its radius increases).', 3),
('25f70d84-0ac7-5b76-9593-ef9b17ff31ca', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 30, 30, 'An electron beam carries a current of 0.50 mA. Calculate the number of electrons passing a point each second. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '3.125e15', 's⁻¹', false, NULL, false, NULL, 'N = I/e = 0.50 × 10⁻³ ÷ 1.60 × 10⁻¹⁹ = 3.12 × 10¹⁵ s⁻¹. Mark scheme (3 marks). C1: N = I/e. C1: substitution. A1: N = 3.12 × 10¹⁵ s⁻¹.', 3),
('451fd2e5-ef88-5ff0-b5db-6672613b0833', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 31, 31, 'Electrons pass undeflected through crossed fields at 3.0 × 10⁷ m s⁻¹. Calculate their kinetic energy, in keV. Take mₑ = 9.11 × 10⁻³¹ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '2.562', 'keV', false, NULL, false, NULL, 'E_k = 0.5 × 9.11 × 10⁻³¹ × (3.0 × 10⁷)² = 4.10 × 10⁻¹⁶ J. In keV: 4.100 × 10⁻¹⁶ ÷ 1.6 × 10⁻¹⁶ = 2.56. Mark scheme (3 marks). C1: ½mv². C1: conversion to keV. A1: E_k = 2.56 keV.', 3),
('8437e2d7-4c60-5bf4-9fa7-829c868ff887', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 32, 32, 'Which observations convinced Thomson that cathode rays were streams of charged particles rather than waves?', NULL, 2, 'multiple_choice'::answer_type, 'They were deflected by electric and magnetic fields in the way expected for negative charges', NULL, false, NULL, false, NULL, 'Deflection by both fields, consistent with F = eE and F = Bev, showed they were charged particles. Mark scheme (4 marks). C1: electric deflection. C1: magnetic deflection. C1: negative charge. A1: B (They were deflected by electric and magnetic fields in the way expected for negative charges).', 4),
('fb6b2703-fda9-5713-80d7-6c6025ec03db', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 33, 33, 'Electrons moving at 2.0 × 10⁷ m s⁻¹ pass between plates 5.0 cm long where E = 1.0 × 10⁴ V m⁻¹. Using e/m = 1.76 × 10¹¹ C kg⁻¹, calculate their sideways deflection, in mm.', NULL, 2, 'numeric'::answer_type, '5.5 mm', 'mm', false, NULL, false, NULL, 'a = (e/m)E = 1.76 × 10¹¹ × 1.0 × 10⁴ = 1.76 × 10¹⁵ m s⁻². t = 0.050 ÷ 2.0 × 10⁷ = 2.5 × 10⁻⁹ s. y = ½at² = 0.5 × 1.76 × 10¹⁵ × (2.5 × 10⁻⁹)² = 0.00550 m. In mm: 0.005500 × 1000 = 5.50. Mark scheme (3 marks). C1: a = (e/m)E. C1: y = ½at². A1: y = 5.50 mm.', 3),
('81e4ed3c-45a1-5f7a-b883-0534ec1d8ad9', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 34, 34, 'An oil drop carries a charge of 8.0 × 10⁻¹⁹ C. How many excess electrons does it carry? Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '5', NULL, false, NULL, false, NULL, 'N = Q/e = 8.0 × 10⁻¹⁹ ÷ 1.60 × 10⁻¹⁹ = 5.0. Mark scheme (3 marks). C1: N = Q/e. C1: whole number. A1: N = 5.0.', 3),
('6cb59acf-d6bb-58fb-9000-b554d7cca80e', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 35, 35, 'How did combining Millikan''s and Thomson''s results give the mass of the electron?', NULL, 2, 'multiple_choice'::answer_type, 'Millikan found e and Thomson found e/m, so m = e ÷ (e/m)', NULL, false, NULL, false, NULL, 'Each experiment alone gives only e or e/m. Mark scheme (3 marks). C1: e from Millikan. C1: e/m from Thomson. A1: C (Millikan found e and Thomson found e/m, so m = e ÷ (e/m)).', 3),
('87d4a581-2b73-5131-942a-48d863eb99e4', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 36, 36, 'Using classical mechanics, calculate the speed of electrons accelerated from rest through 5.0 kV, as a percentage of the speed of light. Take e/m = 1.76 × 10¹¹ C kg⁻¹. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '13.98', '%', false, NULL, false, NULL, 'v = √(2 × 1.76 × 10¹¹ × 5000) = 4.20 × 10⁷ m s⁻¹. Percentage = 4.195 × 10⁷ ÷ 3.00 × 10⁸ × 100 = 14.0 %. Mark scheme (4 marks). C1: v = √(2(e/m)V). C1: ÷ c. C1: percentage. A1: percentage = 14.0%.', 4),
('b14c352e-74ba-5a54-824a-a4f44a034a98', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 37, 37, 'An electron gun accelerates a beam of 0.20 mA through 2.0 kV. Calculate the power delivered to the screen.', NULL, 2, 'numeric'::answer_type, '0.4', 'W', false, NULL, false, NULL, 'P = IV = 0.20 × 10⁻³ × 2.0 × 10³ = 0.40 W. Mark scheme (3 marks). C1: each coulomb gains V joules. C1: P = IV. A1: P = 0.40 W.', 3),
('ae04cf51-5193-5a2f-ba55-348495bfa5c3', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 38, 38, 'In a fine-beam tube, the beam forms a complete circle only when the magnetic field is at right angles to the beam. What happens if the field is at an angle?', NULL, 2, 'multiple_choice'::answer_type, 'The beam follows a helix', NULL, false, NULL, false, NULL, 'The velocity component along the field is unaffected. Mark scheme (3 marks). C1: parallel component unchanged. C1: helix. A1: A (The beam follows a helix).', 3),
('80bbe4a9-e023-5f29-9176-8e6283418482', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 39, 39, 'Electrons accelerated through 250 V follow a circle of radius 6.0 cm in a field of 0.90 mT. Calculate e/m, in units of 10¹¹ C kg⁻¹.', NULL, 2, 'numeric'::answer_type, '1.715', '10¹¹ C kg⁻¹', false, NULL, false, NULL, 'e/m = 2V/(B²r²) = 2 × 250 ÷ ((0.90 × 10⁻³)² × 0.060²) = 1.71 × 10¹¹ C kg⁻¹. Mark scheme (3 marks). C1: e/m = 2V/(B²r²). C1: value. A1: e/m = 1.71 × 10¹¹ C kg⁻¹.', 3),
('f8e30482-7ac9-535e-97fe-f0ff6108faec', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 40, 40, 'In a fine-beam tube, the direction of the magnetic field is reversed. What happens to the beam?', NULL, 2, 'multiple_choice'::answer_type, 'It curves the same amount but in the opposite direction', NULL, false, NULL, false, NULL, 'The force Bev reverses with B. Mark scheme (3 marks). C1: force reverses. C1: same radius. A1: D (It curves the same amount but in the opposite direction).', 3),
('8b2ea2bc-1ade-5737-aac8-5fce583fd24b', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 41, 41, 'In Thomson''s apparatus, plates 3.0 cm apart have a p.d. of 1500 V and the magnetic field is 1.5 mT. Calculate the speed of electrons that pass undeflected.', NULL, 2, 'numeric'::answer_type, '3.333e7', 'm s⁻¹', false, NULL, false, NULL, 'E = 1500 ÷ 0.030 = 5.0 × 10⁴ V m⁻¹. v = E/B = 5.0 × 10⁴ ÷ 1.5 × 10⁻³ = 3.33 × 10⁷ m s⁻¹. Mark scheme (3 marks). C1: E = V/d. C1: v = E/B. A1: v = 3.33 × 10⁷ m s⁻¹.', 3),
('154af481-0d8d-56a2-a847-026004b4c43a', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 42, 42, 'Why must the cathode of an electron gun be heated?', NULL, 2, 'multiple_choice'::answer_type, 'To give electrons enough energy to escape from the metal surface', NULL, false, NULL, false, NULL, 'Electrons need energy at least equal to the work function to leave the metal. Mark scheme (3 marks). C1: energy to escape. C1: thermionic emission. A1: B (To give electrons enough energy to escape from the metal surface).', 3),
('6f53195f-2526-571e-bcf3-8dfc530193bb', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 43, 43, 'In a fine-beam tube with a fixed field of 1.0 mT, the radius r is measured for different accelerating p.d.s V: V/V = 150, 200, 250, 300 and r/cm = 4.13, 4.77, 5.33, 5.84. (a) Show that r² = 2V/((e/m)B²). (b) Calculate the gradient of a graph of r² against V using the first and last points. (c) Calculate e/m, in units of 10¹¹ C kg⁻¹. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.76', '10¹¹ C kg⁻¹', false, NULL, false, NULL, '(a) eV = ½mv² and r = mv/(eB) give r² = 2mV/(eB²) = 2V/((e/m)B²). (b) Gradient = (0.0584² − 0.0413²) ÷ (300 − 150) = 1.14 × 10⁻⁵ m² V⁻¹. (c) e/m = 2 ÷ (B² × gradient) = 2 ÷ ((1.0 × 10⁻³)² × 1.137 × 10⁻⁵) = 1.76 × 10¹¹ C kg⁻¹. Mark scheme (6 marks). B1: r² expression. C1: r in m. C1: gradient. M1: e/m = 2/(B² × gradient). C1: value. A1: e/m = 1.76 × 10¹¹ C kg⁻¹.', 6),
('57b3cdd1-1b23-570d-a337-9ad553ec7341', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 44, 44, 'In a Thomson-type experiment, plates 2.0 cm apart with a p.d. of 400 V and a field of 0.50 mT leave the beam undeflected. With the magnetic field switched off, the beam is deflected by 3.96 mm over the 6.0 cm length of the plates. (a) Calculate the speed of the electrons. (b) Show that e/m = 2yv²/(EL²). (c) Calculate e/m, in units of 10¹¹ C kg⁻¹. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.76', '10¹¹ C kg⁻¹', false, NULL, false, NULL, '(a) E = 400 ÷ 0.020 = 2.0 × 10⁴ V m⁻¹; v = E/B = 2.0 × 10⁴ ÷ 0.50 × 10⁻³ = 4.0 × 10⁷ m s⁻¹. (b) y = ½(e/m)E(L/v)², so e/m = 2yv²/(EL²). (c) e/m = 2 × 3.96 × 10⁻³ × (4.0 × 10⁷)² ÷ (2.0 × 10⁴ × 0.060²) = 1.76 × 10¹¹ C kg⁻¹. Mark scheme (6 marks). C1: E = V/d. C1: v = E/B. M1: y = ½at² with a = (e/m)E. B1: rearranged. C1: value. A1: e/m = 1.76 × 10¹¹ C kg⁻¹.', 6),
('43743c2c-29f6-5575-82c0-e4dd7a5510b1', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 45, 45, 'Classical formulas for electron speed become inaccurate at high speeds. (a) Calculate the accelerating p.d. at which the classical speed of an electron would be 0.10c, in kV. Take e/m = 1.76 × 10¹¹ C kg⁻¹. (b) Suggest why a much higher p.d. is needed to reach 0.99c. Give only the answer to (a). Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '2.557 kV', 'kV', false, NULL, false, NULL, '(a) v = 3.0 × 10⁷ m s⁻¹; V = v²/(2e/m) = (3.0 × 10⁷)² ÷ (2 × 1.76 × 10¹¹) = 2560 V. In kV: 2557 ÷ 1000 = 2.56. (b) Near c the electron''s effective mass grows and extra energy produces less and less increase in speed; it can never reach c. Mark scheme (5 marks). C1: v = 0.10c. C1: V = v²/(2e/m). C1: conversion. B1: relativistic effects near c. A1: V = 2.56 kV.', 5),
('0b5de871-9af3-52cc-b453-c8b3953075b8', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 46, 46, 'Thomson found that e/m for cathode-ray particles was 1.76 × 10¹¹ C kg⁻¹, while for hydrogen ions in electrolysis it was 9.58 × 10⁷ C kg⁻¹. (a) Calculate the ratio of the two values. (b) Assuming equal charges, state what this ratio means. (c) Use e = 1.60 × 10⁻¹⁹ C to find the mass of the cathode-ray particle. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '1837', NULL, false, NULL, false, NULL, '(a) Ratio = 1.76 × 10¹¹ ÷ 9.58 × 10⁷ = 1840. (b) The particle has about 1/1840 of the mass of a hydrogen ion. (c) m = 1.60 × 10⁻¹⁹ ÷ 1.76 × 10¹¹ = 9.09 × 10⁻³¹ kg. Mark scheme (5 marks). C1: ratio. B1: mass ratio for equal charge. C1: m = e/(e/m). C1: value. A1: ratio = 1840.', 5),
('4a8c7b17-1449-5f0d-8cfe-c1174567070b', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 47, 47, 'An oil drop of mass 9.6 × 10⁻¹⁵ kg is held stationary between plates 1.0 cm apart when the p.d. is 980 V. (a) Calculate the charge on the drop. (b) Calculate the number of excess electrons. (c) Explain how many such measurements showed that charge is quantised. Give only the answer to (b). Take g = 9.81 m s⁻² and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '6.006', NULL, false, NULL, false, NULL, '(a) QV/d = mg, so Q = 9.6 × 10⁻¹⁵ × 9.81 × 0.010 ÷ 980 = 9.61 × 10⁻¹⁹ C. (b) N = 9.610 × 10⁻¹⁹ ÷ 1.60 × 10⁻¹⁹ = 6.01. (c) Every drop''s charge was a whole-number multiple of the same value, 1.6 × 10⁻¹⁹ C. Mark scheme (5 marks). M1: QV/d = mg. C1: Q. C1: N = Q/e. B1: all multiples of e. A1: N = 6.01.', 5),
('7909402b-01af-5bbc-85c3-3f8edf301bcf', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 48, 48, 'An electron gun has an accelerating p.d. of 4.0 kV and a beam current of 2.5 mA. (a) Calculate the number of electrons emitted per second. (b) Calculate the speed of the electrons, taking e/m = 1.76 × 10¹¹ C kg⁻¹. (c) Calculate the power delivered by the beam. (d) Suggest what happens to this energy at the screen. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '3.752e7', 'm s⁻¹', false, NULL, false, NULL, '(a) N = 2.5 × 10⁻³ ÷ 1.60 × 10⁻¹⁹ = 1.56 × 10¹⁶ s⁻¹. (b) v = √(2 × 1.76 × 10¹¹ × 4000) = 3.75 × 10⁷ m s⁻¹. (c) P = IV = 2.5 × 10⁻³ × 4000 = 10 W. (d) Most becomes internal energy (heating) of the screen; a little becomes light. Mark scheme (6 marks). C1: N = I/e. C1: v = √(2(e/m)V). C1: P = IV. B1: heating and light. C1: value. A1: v = 3.75 × 10⁷ m s⁻¹.', 6),
('0089dd3d-7638-55bd-9fa4-30e8e628c513', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 49, 49, 'In a fine-beam tube, electrons follow a circle of radius 6.0 cm. The accelerating p.d. and the magnetic field are then both doubled. (a) Show that r ∝ √V/B. (b) Calculate the new radius, in cm. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '4.243 cm', 'cm', false, NULL, false, NULL, '(a) r = √(2mV/e)/B, so r ∝ √V/B. (b) r = 6.0 × √2 ÷ 2 = 4.24 cm. Mark scheme (5 marks). M1: r = √(2mV/e)/B. B1: proportionality. C1: factor √2/2. C1: value. A1: r = 4.24 cm.', 5),
('354e9ba4-6422-54af-9629-972644fa00d9', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 50, 50, 'Electrons moving at 2.0 × 10⁷ m s⁻¹ cross a region 3.0 cm wide containing a field of 1.0 mT and are deflected through 15.3°. (a) Show that the radius of their path in the field is r = (width)/sin θ. (b) Calculate r. (c) Calculate e/m, in units of 10¹¹ C kg⁻¹. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.759', '10¹¹ C kg⁻¹', false, NULL, false, NULL, '(a) The electron follows an arc; the geometry of a circle crossing a strip of width d gives sin θ = d/r. (b) r = 0.030 ÷ sin 15.3° = 0.114 m. (c) e/m = v/(Br) = 2.0 × 10⁷ ÷ (1.0 × 10⁻³ × 0.1137) = 1.76 × 10¹¹ C kg⁻¹. Mark scheme (6 marks). B1: geometry. C1: r. M1: e/m = v/(Br). C1: substitution. C1: value. A1: e/m = 1.76 × 10¹¹ C kg⁻¹.', 6)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('ebcbf942-576d-5997-bd5c-d07c1d8c2eac', '75b54547-f388-5146-9c76-177281239b4c', 'The emission of light by a hot gas', 'A', false, 0),
('c4171826-f3da-58d4-8e3f-8d89e0266be0', '75b54547-f388-5146-9c76-177281239b4c', 'The release of electrons when light shines on a metal', 'B', false, 1),
('361e6dd0-c784-5d3c-92ac-489901c81156', '75b54547-f388-5146-9c76-177281239b4c', 'The release of electrons from the surface of a heated metal', 'C', true, 2),
('9eed3329-9d28-58a0-a819-263397b70a23', '75b54547-f388-5146-9c76-177281239b4c', 'The emission of α-particles from a hot source', 'D', false, 3),
('621667c2-8de5-53e9-a745-2528d55869b1', '91a682a8-1613-5392-9b51-f3201f8ccced', 'The rays carry negative charge', 'A', true, 0),
('220f31d1-fc91-5cc4-9b1d-bc4413535994', '91a682a8-1613-5392-9b51-f3201f8ccced', 'The rays carry positive charge', 'B', false, 1),
('b06a775a-e219-5e27-a552-2e1430d089f3', '91a682a8-1613-5392-9b51-f3201f8ccced', 'The rays are uncharged', 'C', false, 2),
('7549a723-98a5-57d6-a095-c4fa69392620', '91a682a8-1613-5392-9b51-f3201f8ccced', 'The rays are electromagnetic waves', 'D', false, 3),
('9d1f8efd-da93-5ee5-923c-f78c88b72964', 'f3d7e995-334e-52c1-ac2b-8513901bbd67', 'Each metal produces a different particle', 'A', false, 0),
('16d53d31-8727-5fc3-876a-31341d76a7b3', 'f3d7e995-334e-52c1-ac2b-8513901bbd67', 'The rays are a type of light', 'B', false, 1),
('400d5bba-4fdb-5f67-9fc9-d86f089c6415', 'f3d7e995-334e-52c1-ac2b-8513901bbd67', 'The particles are positive ions', 'C', false, 2),
('6e3e10fe-5194-5722-8106-f4a5ec850c7e', 'f3d7e995-334e-52c1-ac2b-8513901bbd67', 'The particles are a common constituent of all atoms', 'D', true, 3),
('2b57dd0e-7d4d-5c48-8387-43b8e30eeeac', 'bb275a1f-aa01-5656-9791-80c1a452a7e8', 'So that the glass does not break', 'A', false, 0),
('96bc1e8b-d647-5018-b827-d3eebb410583', 'bb275a1f-aa01-5656-9791-80c1a452a7e8', 'So that the electrons are not stopped or scattered by collisions with gas molecules', 'B', true, 1),
('c49eb264-edb8-5c96-bd3e-03658dcc0ac2', 'bb275a1f-aa01-5656-9791-80c1a452a7e8', 'So that the electrons can be seen more easily', 'C', false, 2),
('d6be6e2a-08b4-5f42-ba7b-abc9ffcaa00c', 'bb275a1f-aa01-5656-9791-80c1a452a7e8', 'Because gas would absorb the magnetic field', 'D', false, 3),
('6e3329f5-ceba-5f4e-9f45-8920aac3ee19', 'ee26e8a8-a7b3-5c08-95fa-07982c22c73b', 'The electrons themselves glow', 'A', false, 0),
('dab8f058-70ec-5ecc-8e77-9cee67d1f5a6', 'ee26e8a8-a7b3-5c08-95fa-07982c22c73b', 'The magnetic field glows', 'B', false, 1),
('d6e27c46-6774-5b59-8f90-2aeb936914dc', 'ee26e8a8-a7b3-5c08-95fa-07982c22c73b', 'The electrons excite atoms of the low-pressure gas, which then emit light', 'C', true, 2),
('6ef394b5-a90e-5ecd-afe9-af324f923a2e', 'ee26e8a8-a7b3-5c08-95fa-07982c22c73b', 'The glass becomes hot', 'D', false, 3),
